/*
 * node_modules/fs — node:fs-shaped subset on the engine built-ins
 * (mbjs:std / mbjs:os).
 *
 * Synchronous and blocking, like the engine's own file primitives.
 */

import * as std from 'mbjs:std';
import * as os from 'mbjs:os';

function embeddedRead(path) {
    const reader = globalThis.__MOCHI_ASSET_READ__;
    if (typeof reader !== 'function') return undefined;
    return reader(String(path));
}

function embeddedExists(path) {
    const check = globalThis.__MOCHI_ASSET_EXISTS__;
    if (typeof check !== 'function') return false;
    return !!check(String(path));
}

export function readFile(path) {
    const embedded = embeddedRead(path);
    if (embedded !== undefined && embedded !== null)
        return String(embedded);
    const data = std.loadFile(String(path));
    if (data === undefined || data === null)
        throw new Error('fs: readFile("' + path + '") failed');
    return String(data);
}

export function writeFile(path, data) {
    std.writeFile(String(path), data);
}

export function existsSync(path) {
    if (embeddedExists(path)) return true;
    try {
        os.stat(String(path));
        return true;
    } catch (e) {
        return false;
    }
}

export function statSync(path) {
    return os.stat(String(path));
}

export function readdirSync(path) {
    return os.readdir(String(path));
}

export function mkdirSync(path) {
    os.mkdir(String(path), 0o755);
}

export function cwd() {
    const c = os.getcwd();
    return Array.isArray(c) ? String(c[0]) : String(c);
}

export default { readFile, writeFile, existsSync, statSync, readdirSync, mkdirSync, cwd };
